INSERT INTO InfoScie.dbo.first_year (Module_code, Module_description, Module_credits)
VALUES 
('INL110', 'Introduction to Information Science. This module is an introduction to the study field of information science and its various professions. Key concepts that will be discussed include the following: the human as information processor and user; the life-cycle of information in terms of processes, products and role-players; as well as the communication of information. The social-ethical impact of globalisation is included as a key concern, with reference to Africa, the 4th Industrial Revolution and other revolutions to come are addressed as well as core principles such as equity, diversity and inclusion', 16),
('INL120', 'Information organisation, representation and structuring. This module offers a brief overview of the basic principles and processes underlying the organisation, representation, and structuring of information. The process of organising information on the web (such as social networking sites), in multimedia formats, by means of document image processing and in databases is dealt with. Themes on the representation of information through the creation of metadata include various general and domain specific metadata schemas such as Dublin Core for the web, as well as the various retrieval and management tools available for metadata. Practical classes provide a learning environment for students to apply and integrate academic content learned in the theory classes to complete more hands-on projects (e.g. HTML web design). ', 16),
('INL130', 'Personal information management. This module deals with the management of information and knowledge on a personal level which enables an individual to perform their job within an organisational context. Key themes that will be discussed include: creating an environment which is conducive to personal information and knowledge; the skills required to manage personal information and knowledge; the causes and effects of information overload, and the management of this type of phenomenon. The actions, strategies and technologies available for personal information management, as well as the manner in which individuals can switch from personal information management to personal knowledge management; and the various career options in information and knowledge management.', 12);
